//! Replay the account update trace generated by conformance/bench/iavl/run.py.
#![allow(clippy::print_stdout)]

use std::io::{self, BufRead, Read};
use std::path::PathBuf;
use std::sync::Arc;

use iavl::{NodeCache, NodeDb, Tree};
use kvdb::{BackendKind, DbOptions, WriteBatch};

fn main() -> anyhow::Result<()> {
    let dir = PathBuf::from(
        std::env::args_os()
            .nth(1)
            .ok_or_else(|| anyhow::anyhow!("expected a database directory"))?,
    );
    let options = DbOptions {
        backend: BackendKind::RocksDb,
        ..Default::default()
    };
    let db = kvdb::open_backend(&dir, "application", &options)?;
    let mut tree = Tree::open(NodeDb::new(
        Arc::clone(&db),
        b"s/k:acc/".to_vec(),
        NodeCache::new(100_000),
    ))?;
    anyhow::ensure!(tree.version() == 0, "benchmark requires an empty store");
    let mut input = io::stdin().lock();
    while !input.fill_buf()?.is_empty() {
        let mut count = [0; 4];
        input.read_exact(&mut count)?;
        for _ in 0..u32::from_be_bytes(count) {
            let mut row = [0; 100];
            input.read_exact(&mut row)?;
            tree.set(row[..20].to_vec(), row[20..].to_vec())?;
        }
        let commit = tree.save_version()?;
        println!("{}", hex::encode(commit.root_hash));
        if commit.version > 100 && commit.version % 10 == 0 {
            let mut batch = WriteBatch::new();
            tree.prune(|v| v > commit.version - 100, &mut batch)?;
            db.write(batch)?;
        }
    }
    db.flush()?;
    Ok(())
}
